import openpyxl
from datetime import datetime

# Load the workbook
wb = openpyxl.load_workbook('input.xlsx')
ws = wb.active

# Extract holiday data from columns H, I, J (Holiday Name, Date, Type)
# The holiday data starts from row 2 and continues until empty rows are encountered
# Based on the sample, holidays are in rows 2-16 (columns H, I, J)
holidays = {}
for row in range(2, ws.max_row + 1):
    holiday_date_cell = ws.cell(row=row, column=9)  # Column I
    holiday_type_cell = ws.cell(row=row, column=10)  # Column J

    if holiday_date_cell.value is None or holiday_type_cell.value is None:
        continue

    # Parse the holiday date
    if isinstance(holiday_date_cell.value, datetime):
        holiday_date = holiday_date_cell.value.date()
    elif isinstance(holiday_date_cell.value, str):
        try:
            holiday_date = datetime.strptime(holiday_date_cell.value, '%Y-%m-%d %H:%M:%S').date()
        except:
            continue
    else:
        continue

    holiday_type = holiday_type_cell.value
    holidays[holiday_date] = holiday_type

# Process each row in the main data (columns A-E)
# Column A: DATE, Column E: WORKDAY
for row in range(2, ws.max_row + 1):
    date_cell = ws.cell(row=row, column=1)  # Column A
    workday_cell = ws.cell(row=row, column=5)  # Column E

    if date_cell.value is None:
        continue

    # Parse the date
    if isinstance(date_cell.value, datetime):
        date_val = date_cell.value.date()
    elif isinstance(date_cell.value, str):
        try:
            date_val = datetime.strptime(date_cell.value, '%Y-%m-%d %H:%M:%S').date()
        except:
            continue
    else:
        continue

    # Check if the date is a holiday
    if date_val in holidays:
        workday_cell.value = holidays[date_val]
    else:
        # Get the day of the week
        day_of_week = date_val.strftime('%a')  # Mon, Tue, Wed, etc.
        workday_cell.value = day_of_week

# Save the workbook
wb.save('output.xlsx')
