import openpyxl
from datetime import datetime

# Load the workbook
wb = openpyxl.load_workbook('input.xlsx')
ws = wb.active  # Assuming the active sheet is 'Лист1'

# Define the range of data (rows 2 to 41, columns A to I)
# Column C is index 3, Column I is index 9, Column M is index 13
data_start_row = 2
data_end_row = 41

# Step 1: Identify the latest Entry Time for each Name
# We need to group by Name (Column C) and find the max Entry Time (Column I)
name_latest_time = {}

for row in range(data_start_row, data_end_row + 1):
    name = ws.cell(row=row, column=3).value  # Column C
    entry_time = ws.cell(row=row, column=9).value  # Column I

    if name is not None and entry_time is not None:
        # Ensure entry_time is a datetime object
        if isinstance(entry_time, str):
            try:
                entry_time = datetime.strptime(entry_time, "%Y-%m-%d %H:%M:%S.%f")
            except ValueError:
                try:
                    entry_time = datetime.strptime(entry_time, "%Y-%m-%d %H:%M:%S")
                except ValueError:
                    continue
        elif not isinstance(entry_time, datetime):
            continue

        if name not in name_latest_time:
            name_latest_time[name] = entry_time
        else:
            if entry_time > name_latest_time[name]:
                name_latest_time[name] = entry_time

# Step 2: Mark each row as 'Latest' or 'Not Latest'
for row in range(data_start_row, data_end_row + 1):
    name = ws.cell(row=row, column=3).value  # Column C
    entry_time = ws.cell(row=row, column=9).value  # Column I

    if name is None or entry_time is None:
        ws.cell(row=row, column=13).value = ""  # Column M
        continue

    # Ensure entry_time is a datetime object for comparison
    if isinstance(entry_time, str):
        try:
            entry_time = datetime.strptime(entry_time, "%Y-%m-%d %H:%M:%S.%f")
        except ValueError:
            try:
                entry_time = datetime.strptime(entry_time, "%Y-%m-%d %H:%M:%S")
            except ValueError:
                ws.cell(row=row, column=13).value = ""
                continue
    elif not isinstance(entry_time, datetime):
        ws.cell(row=row, column=13).value = ""
        continue

    if name in name_latest_time:
        if entry_time == name_latest_time[name]:
            ws.cell(row=row, column=13).value = "Latest"
        else:
            ws.cell(row=row, column=13).value = "Not Latest"
    else:
        ws.cell(row=row, column=13).value = ""

# Save the result
wb.save('output.xlsx')
